-- ABOUT / PROFESSIONAL PROFILE
update public.about
set
  professional_title_en = 'AI, Data & Quantitative Solutions | Software Development & Applied AI',
  professional_title_pt = 'Soluções em IA, Dados e Computação Quantitativa | Desenvolvimento de Software & IA Aplicada',
  intro_en = $$AI, data, and quantitative solutions professional, Physicist, MSc in Physics, and PhD researcher in Electronic Engineering and Computing at ITA. Experienced in AI agents, AI-assisted software development, data engineering, clustering and data optimization, data-driven decision systems, quantitative modeling, and scientific computing.$$,
  intro_pt = $$Profissional de soluções em IA, dados e computação quantitativa, Físico, Mestre em Física e doutorando em Engenharia Eletrônica e Computação no ITA. Experiência com agentes de IA, desenvolvimento de software assistido por IA, engenharia de dados, clustering e otimização de dados, sistemas de decisão orientados por dados, modelagem quantitativa e computação científica.$$,
  value_proposition_en = $$I build software and AI solutions across Microsoft and open-source ecosystems, combining quantitative reasoning, enterprise data, and applied AI. Solution Architecture · Software Engineering · AI Agents · Data Engineering.$$,
  value_proposition_pt = $$Desenvolvo soluções de software e IA nos ecossistemas Microsoft e open source, combinando raciocínio quantitativo, dados corporativos e IA aplicada. Arquitetura de Soluções · Engenharia de Software · Agentes de IA · Engenharia de Dados.$$,
  description_en = $$AI, data, and quantitative solutions professional, Physicist, MSc in Physics, and PhD researcher in Electronic Engineering and Computing at ITA. Experienced in AI agents, AI-assisted software development, data engineering, clustering and data optimization, data-driven decision systems, quantitative modeling, and scientific computing.
At ProNext, I develop AI-assisted software, LLM-based agents, data solutions, Power Apps, tool integrations and automated workflows for enterprise problems within the Microsoft ecosystem, including SharePoint, Dataverse and Power Automate.
My doctoral research at ITA investigates GNSS-denied autonomous navigation integrating classical and quantum sensors, sensor fusion, state estimation, intelligent computational methods and validation strategies for safety-critical systems.
As President and Co-Founder of the Foton Institute, I lead multidisciplinary R&D&I at the interface of scientific research, technology development and industrial application, including system architecture, PoC/MVP development, optimization and data-driven operational decision-making.
I also co-founded the Brazilian Quantum Computing Academic League movement, supporting 10+ academic leagues across Brazil. From 2023–2026, I delivered 50+ in-person talks across Brazil’s five macro-regions and organized, coordinated or curated 15+ events and technical tracks in Quantum, Security and Emerging Technologies.$$,
  description_pt = $$Profissional de soluções em IA, dados e computação quantitativa, Físico, Mestre em Física e doutorando em Engenharia Eletrônica e Computação no ITA. Experiência com agentes de IA, desenvolvimento de software assistido por IA, engenharia de dados, clustering e otimização de dados, sistemas de decisão orientados por dados, modelagem quantitativa e computação científica.
Na ProNext, desenvolvo software assistido por IA, agentes baseados em LLM, soluções de dados, Power Apps, integrações de ferramentas e fluxos automatizados para problemas corporativos no ecossistema Microsoft, incluindo SharePoint, Dataverse e Power Automate.
Minha pesquisa de doutorado no ITA investiga navegação autônoma GNSS-denied integrando sensores clássicos e quânticos, fusão de sensores, estimação de estado, métodos computacionais inteligentes e estratégias de validação para sistemas críticos.
Como Presidente e Cofundador do Instituto Foton, lidero P&D&I multidisciplinar na interface entre pesquisa científica, desenvolvimento tecnológico e aplicação industrial, incluindo arquitetura de sistemas, desenvolvimento de PoCs/MVPs, otimização e decisão operacional orientada por dados.
Também cofundei o movimento brasileiro de Ligas Acadêmicas de Computação Quântica, apoiando 10+ ligas acadêmicas no Brasil. Entre 2023–2026, realizei 50+ palestras presenciais nas cinco macrorregiões do país e organizei, coordenei ou curei 15+ eventos e trilhas técnicas em Quantum, Segurança e Tecnologias Emergentes.$$,
  content_en = coalesce(content_en, '{}'::jsonb) || '{"name":"Leonardo Camargo Rossato","title":"About","headline":"AI, Data & Quantitative Solutions | Software Development & Applied AI","professionalTitle":"AI, Data & Quantitative Solutions | Software Development & Applied AI","intro":"AI, data, and quantitative solutions professional, Physicist, MSc in Physics, and PhD researcher in Electronic Engineering and Computing at ITA. Experienced in AI agents, AI-assisted software development, data engineering, clustering and data optimization, data-driven decision systems, quantitative modeling, and scientific computing.","valueProposition":"I build software and AI solutions across Microsoft and open-source ecosystems, combining quantitative reasoning, enterprise data, and applied AI. Solution Architecture · Software Engineering · AI Agents · Data Engineering.","bio":["AI, data, and quantitative solutions professional, Physicist, MSc in Physics, and PhD researcher in Electronic Engineering and Computing at ITA. Experienced in AI agents, AI-assisted software development, data engineering, clustering and data optimization, data-driven decision systems, quantitative modeling, and scientific computing.","At ProNext, I develop AI-assisted software, LLM-based agents, data solutions, Power Apps, tool integrations and automated workflows for enterprise problems within the Microsoft ecosystem, including SharePoint, Dataverse and Power Automate.","My doctoral research at ITA investigates GNSS-denied autonomous navigation integrating classical and quantum sensors, sensor fusion, state estimation, intelligent computational methods and validation strategies for safety-critical systems.","As President and Co-Founder of the Foton Institute, I lead multidisciplinary R&D&I at the interface of scientific research, technology development and industrial application, including system architecture, PoC/MVP development, optimization and data-driven operational decision-making.","I also co-founded the Brazilian Quantum Computing Academic League movement, supporting 10+ academic leagues across Brazil. From 2023–2026, I delivered 50+ in-person talks across Brazil’s five macro-regions and organized, coordinated or curated 15+ events and technical tracks in Quantum, Security and Emerging Technologies."],"location":"São José dos Campos, Brazil","email":"leo.c.rossato@gmail.com","experiences":[{"id":"pronext","order":1,"title":"Software Development & Applied AI","organization":"ProNext · Internship Contract | Remote","period":"2026 — Present","description":"Develop AI-assisted software, LLM-based agents, data solutions, Power Apps, tool integrations and automated workflows for enterprise problems within the Microsoft ecosystem, including SharePoint, Dataverse and Power Automate. Build agentic solutions and GPT integrations using OpenAI API and Microsoft Copilot interfaces, prompt/context engineering, APIs, guardrails and enterprise knowledge-source integrations."},{"id":"ita","order":2,"title":"PhD Researcher — Autonomous Navigation & Hybrid Sensing","organization":"Aeronautics Institute of Technology — ITA","period":"2026 — Present","description":"Research GNSS-denied autonomous navigation integrating classical and quantum sensors, sensor fusion, state estimation, intelligent computational methods and validation strategies for safety-critical systems."},{"id":"foton","order":3,"title":"President & Co-Founder | Technology & R&D Lead (Volunteer)","organization":"Institute of Quantum Sciences and Technologies — Foton Institute","organizationUrl":"https://institutofoton.com.br/","period":"2025 — Present","description":"Lead multidisciplinary R&D&I at the interface of scientific research, technology development and industrial application; act as Project Manager across multidisciplinary teams, guiding system architecture, PoC/MVP development, optimization and data-driven operational decision-making. Apply a structured AI-assisted development workflow separating requirements and architecture planning from implementation, testing and iterative refinement with AI coding assistants."},{"id":"ufrgs","order":4,"title":"Researcher — Econophysics, Data Science & Complex Systems","organization":"Federal University of Rio Grande do Sul — UFRGS","period":"2022 — 2025","description":"Built end-to-end Python/Jupyter data pipelines covering ETL, cleaning, standardization, integration, validation/QA, statistical modeling and visualization for heterogeneous socioeconomic datasets from Brazil, the United States and Latin America. Worked extensively with clustering and data optimization, graph-based clustering, statistical inference, scikit-learn workflows, visual analytics and reproducible pipelines."},{"id":"ufsm","order":5,"title":"Researcher — Computational Physics & Condensed Matter","organization":"Federal University of Santa Maria — UFSM","period":"2020 — 2022","description":"Automated reproducible pre-processing, execution and post-processing pipelines using Jupyter, Linux, Fortran/C/Shell; processed large simulation datasets and optimized numerical routines by approximately 50%."}],"education":[{"id":"ita-phd","order":1,"institution":"Aeronautics Institute of Technology (ITA)","degree":"PhD Candidate","field":"Electronic Engineering and Computing","period":"2026 — Present"},{"id":"ufrgs-msc","order":2,"institution":"Federal University of Rio Grande do Sul (UFRGS)","degree":"MSc in Physics","field":"Econophysics, Data Science & Statistical Physics","period":"2022 — 2025"},{"id":"ufsm-bsc","order":3,"institution":"Federal University of Santa Maria (UFSM)","degree":"BSc in Physics","field":"Computational & Condensed-Matter Physics","period":"2020 — 2022"},{"id":"ufsm-chemical","order":4,"institution":"Federal University of Santa Maria (UFSM)","degree":"Chemical Engineering","field":"Partial undergraduate studies","period":"2016 — 2020"}],"researchTimeline":[{"id":"nav","order":1,"period":"2026 → Present","title":"Autonomous Navigation & Hybrid Sensing","institution":"ITA","description":"GNSS-denied navigation, classical and quantum sensors, sensor fusion, state estimation, intelligent computational methods and validation strategies."},{"id":"econ","order":2,"period":"2022 → 2025","title":"Econophysics, Data Science & Complex Systems","institution":"UFRGS","description":"ETL, clustering, graph algorithms, statistical inference, visual analytics and reproducible pipelines for heterogeneous socioeconomic datasets."},{"id":"cmp","order":3,"period":"2020 → 2022","title":"Computational Physics & Condensed Matter","institution":"UFSM","description":"Reproducible computational pipelines, numerical methods and simulation of condensed-matter systems."}],"areas":["AI Agents","Software Engineering","Data Engineering","Quantitative Modeling","Scientific Computing","Solution Architecture","Clustering","Statistical Inference","Sensor Fusion","State Estimation","Quantum Technologies"],"publications":[{"id":"epjb-2024","order":1,"year":2024,"title":"Analysis of socioeconomic indicators in the United States, Brazil, and other Latin American countries using econophysics techniques.","venue":"European Physical Journal B, 97, 137.","authors":["L. C. Rossato","J. R. Iglesias","S. Gonçalves"]},{"id":"physica-2023","order":2,"year":2023,"title":"The Ising bilayer honeycomb lattice: A cluster mean-field study.","venue":"Physica A, 621, 128778.","authors":["L. C. Rossato","F. M. Zimmer","C. V. Morais","M. Schmidt"]}],"scienceCommunication":"Co-Founder of the Brazilian Quantum Computing Academic League movement; founded and supported 10+ academic leagues across Brazil (2024–2026/1). Delivered 50+ in-person talks (2023–2026) across Brazil’s five macro-regions. Organized, coordinated or curated 15+ events and technical tracks in Quantum, Security and Emerging Technologies. Selected through the Young Scholars Initiative as the only Brazilian among seven internationally sponsored researchers for the 2023 Conference on Complex Systems (CCS).","speakerPortfolioUrl":"https://leonardo-camargo-rossato.lovable.app/"}'::jsonb,
  content_pt = coalesce(content_pt, '{}'::jsonb) || '{"name":"Leonardo Camargo Rossato","title":"Sobre","headline":"Soluções em IA, Dados e Computação Quantitativa | Desenvolvimento de Software & IA Aplicada","professionalTitle":"Soluções em IA, Dados e Computação Quantitativa | Desenvolvimento de Software & IA Aplicada","intro":"Profissional de soluções em IA, dados e computação quantitativa, Físico, Mestre em Física e doutorando em Engenharia Eletrônica e Computação no ITA. Experiência com agentes de IA, desenvolvimento de software assistido por IA, engenharia de dados, clustering e otimização de dados, sistemas de decisão orientados por dados, modelagem quantitativa e computação científica.","valueProposition":"Desenvolvo soluções de software e IA nos ecossistemas Microsoft e open source, combinando raciocínio quantitativo, dados corporativos e IA aplicada. Arquitetura de Soluções · Engenharia de Software · Agentes de IA · Engenharia de Dados.","bio":["Profissional de soluções em IA, dados e computação quantitativa, Físico, Mestre em Física e doutorando em Engenharia Eletrônica e Computação no ITA. Experiência com agentes de IA, desenvolvimento de software assistido por IA, engenharia de dados, clustering e otimização de dados, sistemas de decisão orientados por dados, modelagem quantitativa e computação científica.","Na ProNext, desenvolvo software assistido por IA, agentes baseados em LLM, soluções de dados, Power Apps, integrações de ferramentas e fluxos automatizados para problemas corporativos no ecossistema Microsoft, incluindo SharePoint, Dataverse e Power Automate.","Minha pesquisa de doutorado no ITA investiga navegação autônoma GNSS-denied integrando sensores clássicos e quânticos, fusão de sensores, estimação de estado, métodos computacionais inteligentes e estratégias de validação para sistemas críticos.","Como Presidente e Cofundador do Instituto Foton, lidero P&D&I multidisciplinar na interface entre pesquisa científica, desenvolvimento tecnológico e aplicação industrial, incluindo arquitetura de sistemas, desenvolvimento de PoCs/MVPs, otimização e decisão operacional orientada por dados.","Também cofundei o movimento brasileiro de Ligas Acadêmicas de Computação Quântica, apoiando 10+ ligas acadêmicas no Brasil. Entre 2023–2026, realizei 50+ palestras presenciais nas cinco macrorregiões do país e organizei, coordenei ou curei 15+ eventos e trilhas técnicas em Quantum, Segurança e Tecnologias Emergentes."],"location":"São José dos Campos, Brasil","email":"leo.c.rossato@gmail.com","areas":["Agentes de IA","Engenharia de Software","Engenharia de Dados","Modelagem Quantitativa","Computação Científica","Arquitetura de Soluções","Clustering","Inferência Estatística","Fusão de Sensores","Estimação de Estado","Tecnologias Quânticas"],"scienceCommunication":"Cofundador do movimento brasileiro de Ligas Acadêmicas de Computação Quântica; fundou e apoiou 10+ ligas acadêmicas no Brasil (2024–2026/1). Realizou 50+ palestras presenciais (2023–2026) nas cinco macrorregiões do país. Organizou, coordenou ou curei 15+ eventos e trilhas técnicas em Quantum, Segurança e Tecnologias Emergentes. Selecionado pelo Young Scholars Initiative como o único brasileiro entre sete pesquisadores internacionalmente financiados para a Conference on Complex Systems (CCS) de 2023.","speakerPortfolioUrl":"https://leonardo-camargo-rossato.lovable.app/","experiences":[{"id":"pronext","order":1,"title":"Desenvolvimento de Software & IA Aplicada","organization":"ProNext · Contrato de Estágio | Remoto","period":"2026 — Presente","description":"Desenvolvo software assistido por IA, agentes baseados em LLM, soluções de dados, Power Apps, integrações de ferramentas e fluxos automatizados para problemas corporativos no ecossistema Microsoft, incluindo SharePoint, Dataverse e Power Automate. Construo soluções agênticas e integrações com GPT usando OpenAI API e interfaces Microsoft Copilot, engenharia de prompt/contexto, APIs, guardrails e integração com fontes de conhecimento corporativas."},{"id":"ita","order":2,"title":"Pesquisador de Doutorado — Navegação Autônoma & Sensoriamento Híbrido","organization":"Instituto Tecnológico de Aeronáutica — ITA","period":"2026 — Presente","description":"Pesquisa em navegação autônoma GNSS-denied integrando sensores clássicos e quânticos, fusão de sensores, estimação de estado, métodos computacionais inteligentes e estratégias de validação para sistemas críticos."},{"id":"foton","order":3,"title":"Presidente & Cofundador | Líder de Tecnologia & P&D (Voluntário)","organization":"Instituto de Ciências e Tecnologias Quânticas — Instituto Foton","organizationUrl":"https://institutofoton.com.br/","period":"2025 — Presente","description":"Lidero P&D&I multidisciplinar na interface entre pesquisa científica, desenvolvimento tecnológico e aplicação industrial; atuo como Project Manager em equipes multidisciplinares, orientando arquitetura de sistemas, desenvolvimento de PoCs/MVPs, otimização e tomada de decisão operacional orientada por dados."},{"id":"ufrgs","order":4,"title":"Pesquisador — Econofísica, Ciência de Dados & Sistemas Complexos","organization":"Universidade Federal do Rio Grande do Sul — UFRGS","period":"2022 — 2025","description":"Desenvolvi pipelines end-to-end em Python/Jupyter cobrindo ETL, limpeza, padronização, integração, validação/QA, modelagem estatística e visualização para bases socioeconômicas heterogêneas do Brasil, Estados Unidos e América Latina, com forte atuação em clustering, otimização de dados, clustering baseado em grafos, inferência estatística e pipelines reprodutíveis."},{"id":"ufsm","order":5,"title":"Pesquisador — Física Computacional & Matéria Condensada","organization":"Universidade Federal de Santa Maria — UFSM","period":"2020 — 2022","description":"Automatizei pipelines reprodutíveis de pré-processamento, execução e pós-processamento usando Jupyter, Linux, Fortran/C/Shell; processei grandes conjuntos de dados de simulação e otimizei rotinas numéricas em aproximadamente 50%."}],"education":[{"id":"ita-phd","order":1,"institution":"Instituto Tecnológico de Aeronáutica (ITA)","degree":"Doutorando","field":"Engenharia Eletrônica e Computação","period":"2026 — Presente"},{"id":"ufrgs-msc","order":2,"institution":"Universidade Federal do Rio Grande do Sul (UFRGS)","degree":"Mestrado em Física","field":"Econofísica, Ciência de Dados & Física Estatística","period":"2022 — 2025"},{"id":"ufsm-bsc","order":3,"institution":"Universidade Federal de Santa Maria (UFSM)","degree":"Bacharelado em Física","field":"Física Computacional & Matéria Condensada","period":"2020 — 2022"},{"id":"ufsm-chemical","order":4,"institution":"Universidade Federal de Santa Maria (UFSM)","degree":"Engenharia Química","field":"Graduação parcial","period":"2016 — 2020"}],"researchTimeline":[{"id":"nav","order":1,"period":"2026 → Presente","title":"Navegação Autônoma & Sensoriamento Híbrido","institution":"ITA","description":"Navegação GNSS-denied, sensores clássicos e quânticos, fusão de sensores, estimação de estado, métodos computacionais inteligentes e estratégias de validação."},{"id":"econ","order":2,"period":"2022 → 2025","title":"Econofísica, Ciência de Dados & Sistemas Complexos","institution":"UFRGS","description":"ETL, clustering, algoritmos em grafos, inferência estatística, análise visual e pipelines reprodutíveis para bases socioeconômicas heterogêneas."},{"id":"cmp","order":3,"period":"2020 → 2022","title":"Física Computacional & Matéria Condensada","institution":"UFSM","description":"Pipelines computacionais reprodutíveis, métodos numéricos e simulação de sistemas de matéria condensada."}],"publications":[{"id":"epjb-2024","order":1,"year":2024,"title":"Analysis of socioeconomic indicators in the United States, Brazil, and other Latin American countries using econophysics techniques.","venue":"European Physical Journal B, 97, 137.","authors":["L. C. Rossato","J. R. Iglesias","S. Gonçalves"]},{"id":"physica-2023","order":2,"year":2023,"title":"The Ising bilayer honeycomb lattice: A cluster mean-field study.","venue":"Physica A, 621, 128778.","authors":["L. C. Rossato","F. M. Zimmer","C. V. Morais","M. Schmidt"]}]}'::jsonb,
