  short_description_en = $$End-to-end enterprise platform for organizational governance, data and analytics, developed with React/TypeScript, SharePoint Framework (SPFx), SharePoint CLI, SharePoint data repositories, APIs and automated workflows.$$,
  short_description_pt = $$Plataforma corporativa end-to-end para governança organizacional, dados e analytics, desenvolvida com React/TypeScript, SharePoint Framework (SPFx), SharePoint CLI, repositórios de dados SharePoint, APIs e fluxos automatizados.$$,
  sections_en = coalesce(sections_en, '{}'::jsonb) || '{"overview":["Foton Hub is an end-to-end enterprise platform for organizational governance, data and analytics inside the Microsoft ecosystem.","It centralizes people, organizations, projects, documents, links, tools, analytics environments and institutional knowledge in a unified application layer over SharePoint and Microsoft 365."],"challenge":["Institutional information was distributed across multiple SharePoint lists, libraries, pages and internal resources, making navigation, governance and knowledge access harder for users."],"solution":["The platform creates a modular React/TypeScript and SPFx experience over SharePoint data repositories, APIs and automated workflows, hiding infrastructure complexity behind a coherent web interface.","Controlled GPT integrations provide AI-assisted access to organizational knowledge and platform data."],"architecture":{"body":"The solution combines a React/TypeScript front end, SPFx integration, SharePoint lists and libraries, Microsoft 365 services, APIs, automated workflows and controlled GPT integrations.","items":["React / TypeScript","SPFx / SharePoint Framework","SharePoint CLI","SharePoint data repositories","APIs","Automated workflows","GPT integrations"]},"features":["Organizational governance","People and organization management","Projects and document access","Links and internal tools","Analytics environments","Enterprise data and knowledge access","Controlled GPT-assisted knowledge access"],"role":["End-to-end solution architecture and implementation across the application layer, Microsoft ecosystem integration, data access patterns, reusable components and AI-assisted knowledge access."],"results":["A unified institutional environment that reduces information fragmentation and supports modular expansion across governance, data, analytics and knowledge workflows."],"technologies":["React","TypeScript","SPFx","SharePoint Framework","SharePoint CLI","Microsoft 365","SharePoint","APIs","Automated Workflows","GPT Integrations"]}'::jsonb,
  sections_pt = coalesce(sections_pt, '{}'::jsonb) || '{"overview":["O Foton Hub é uma plataforma corporativa end-to-end para governança organizacional, dados e analytics no ecossistema Microsoft.","Centraliza pessoas, organizações, projetos, documentos, links, ferramentas, ambientes analíticos e conhecimento institucional em uma camada de aplicação unificada sobre SharePoint e Microsoft 365."],"challenge":["As informações institucionais estavam distribuídas em múltiplas listas, bibliotecas, páginas e recursos internos do SharePoint, dificultando navegação, governança e acesso ao conhecimento."],"solution":["A plataforma cria uma experiência modular em React/TypeScript e SPFx sobre repositórios de dados SharePoint, APIs e fluxos automatizados, escondendo a complexidade da infraestrutura atrás de uma interface web coerente.","Integrações controladas com GPT oferecem acesso assistido por IA ao conhecimento organizacional e aos dados da plataforma."],"architecture":{"body":"A solução combina front-end React/TypeScript, integração SPFx, listas e bibliotecas SharePoint, serviços Microsoft 365, APIs, fluxos automatizados e integrações controladas com GPT.","items":["React / TypeScript","SPFx / SharePoint Framework","SharePoint CLI","Repositórios SharePoint","APIs","Fluxos automatizados","Integrações GPT"]},"features":["Governança organizacional","Gestão de pessoas e organizações","Projetos e documentos","Links e ferramentas internas","Ambientes analíticos","Dados corporativos e acesso ao conhecimento","Acesso ao conhecimento assistido por GPT"],"role":["Arquitetura e implementação end-to-end da solução, incluindo camada de aplicação, integração com o ecossistema Microsoft, padrões de acesso a dados, componentes reutilizáveis e acesso ao conhecimento assistido por IA."],"results":["Um ambiente institucional unificado que reduz fragmentação de informações e permite expansão modular em governança, dados, analytics e fluxos de conhecimento."],"technologies":["React","TypeScript","SPFx","SharePoint Framework","SharePoint CLI","Microsoft 365","SharePoint","APIs","Fluxos Automatizados","Integrações GPT"]}'::jsonb,
  technologies = array['React','TypeScript','SPFx','SharePoint Framework','SharePoint CLI','Microsoft 365','SharePoint','SharePoint Lists / Libraries','APIs','Automated Workflows','GPT Integrations'],
  updated_at = now()
where id = 'foton-hub';

-- CITIES COMPARING
update public.projects
set
  subtitle_en = 'Quantitative & Data Platform',
  subtitle_pt = 'Plataforma Quantitativa & de Dados',
  category_en = 'Data Engineering / Quantitative Analysis',
  category_pt = 'Engenharia de Dados / Análise Quantitativa',
  short_description_en = $$Full-stack quantitative and data platform derived from MSc research for socioeconomic analysis, combining data engineering, PostgreSQL/SQL and CRUD, clustering, quantitative methods, statistical analysis and interactive visualization.$$,
  short_description_pt = $$Plataforma full-stack quantitativa e de dados derivada da pesquisa de mestrado para análise socioeconômica, combinando engenharia de dados, PostgreSQL/SQL e CRUD, clustering, métodos quantitativos, análise estatística e visualização interativa.$$,
  sections_en = coalesce(sections_en, '{}'::jsonb) || '{"overview":["Cities Comparing is a quantitative and data platform derived from MSc research at UFRGS for socioeconomic analysis across heterogeneous datasets from Brazil, the United States and Latin America.","It combines data engineering, quantitative methods, clustering, statistical analysis and interactive visualization in a browser-accessible analytical environment."],"challenge":["Socioeconomic datasets from different countries use different structures, scales and conventions, which makes direct comparison difficult without substantial cleaning, standardization, integration and validation."],"approach":["The research workflow covered ETL, cleaning, standardization, integration, validation/QA, statistical modeling and reproducible analysis pipelines.","Analytical methods included clustering, graph-based clustering, statistical inference and visual analytics."],"architecture":{"body":"The project connects Python/Jupyter research workflows to data processing, PostgreSQL/SQL and CRUD where implemented, and an interactive Streamlit interface for exploration and comparison.","items":["ETL / preprocessing","PostgreSQL / SQL","CRUD","Clustering","Graph-based methods","Statistical analysis","Streamlit / Plotly"]},"features":["Cross-country socioeconomic comparison","Heterogeneous dataset integration","Scatter and distribution analysis","Clustering and graph-based methods","Interactive visual analytics","Reproducible research workflows"],"role":["End-to-end research software development covering data preparation, quantitative analysis, algorithm development, validation and interactive visualization."],"results":["A reusable analytical platform that transforms heterogeneous socioeconomic data into comparable, inspectable and reproducible quantitative workflows."],"technologies":["Python","PostgreSQL","SQL","CRUD","Pandas","Streamlit","Jupyter","scikit-learn","Clustering","Graph Algorithms","Statistical Analysis","Plotly","Data Engineering"]}'::jsonb,
  sections_pt = coalesce(sections_pt, '{}'::jsonb) || '{"overview":["O Cities Comparing é uma plataforma quantitativa e de dados derivada da pesquisa de mestrado na UFRGS para análise socioeconômica de bases heterogêneas do Brasil, Estados Unidos e América Latina.","Combina engenharia de dados, métodos quantitativos, clustering, análise estatística e visualização interativa em um ambiente analítico acessível pelo navegador."],"challenge":["Bases socioeconômicas de diferentes países usam estruturas, escalas e convenções distintas, dificultando comparações diretas sem limpeza, padronização, integração e validação."],"approach":["O fluxo de pesquisa envolveu ETL, limpeza, padronização, integração, validação/QA, modelagem estatística e pipelines reprodutíveis de análise.","Os métodos analíticos incluem clustering, clustering baseado em grafos, inferência estatística e análise visual."],"architecture":{"body":"O projeto conecta fluxos de pesquisa em Python/Jupyter ao processamento de dados, PostgreSQL/SQL e CRUD onde implementados, além de uma interface Streamlit interativa para exploração e comparação.","items":["ETL / pré-processamento","PostgreSQL / SQL","CRUD","Clustering","Métodos baseados em grafos","Análise estatística","Streamlit / Plotly"]},"features":["Comparação socioeconômica entre países","Integração de bases heterogêneas","Análises de dispersão e distribuição","Clustering e métodos baseados em grafos","Análise visual interativa","Fluxos reprodutíveis de pesquisa"],"role":["Desenvolvimento end-to-end do software de pesquisa, cobrindo preparação de dados, análise quantitativa, desenvolvimento de algoritmos, validação e visualização interativa."],"results":["Uma plataforma analítica reutilizável que transforma dados socioeconômicos heterogêneos em fluxos quantitativos comparáveis, inspecionáveis e reprodutíveis."],"technologies":["Python","PostgreSQL","SQL","CRUD","Pandas","Streamlit","Jupyter","scikit-learn","Clustering","Algoritmos em Grafos","Análise Estatística","Plotly","Engenharia de Dados"]}'::jsonb,
  technologies = array['Python','PostgreSQL','SQL','CRUD','Pandas','Streamlit','Jupyter','scikit-learn','Clustering','Graph Algorithms','Statistical Analysis','Plotly','Data Engineering'],
  updated_at = now()
where id = 'city-comparing' or slug = 'cities-comparing';

