  short_description_pt = $$Plataforma literária assistida por IA para escritores e engajamento de leitores, combinando ambiente narrativo interativo, chatbot de IA fundamentado no conteúdo da obra e um repositório vivo de conhecimento.$$,
  sections_en = coalesce(sections_en, '{}'::jsonb) || '{"overview":["Hamlet is an AI-assisted literary platform for writers and reader engagement, combining an interactive narrative environment, an AI chatbot grounded in book content and a living knowledge repository."],"challenge":["The project explores how a literary universe can remain coherent while allowing readers to navigate characters, documents, media and AI-mediated interactions."],"solution":["The platform combines a web application, narrative content, document and media experiences, a grounded AI chatbot and a living knowledge repository.","Multi-agent orchestration combining RAG and model fine-tuning for character-specific AI agents is currently under development."],"features":["Interactive narrative environment","AI chatbot grounded in book content","Living knowledge repository","Document and media experiences","Character-specific AI agent research in progress"],"role":["Product and software development across narrative experience, application structure, AI integration and evolving knowledge-system architecture."],"technologies":["AI Chatbot","LLM","RAG","Knowledge Repository","Multi-Agent Systems","Fine-Tuning","React","TypeScript","Web Application"]}'::jsonb,
  sections_pt = coalesce(sections_pt, '{}'::jsonb) || '{"overview":["Hamlet é uma plataforma literária assistida por IA para escritores e engajamento de leitores, combinando ambiente narrativo interativo, chatbot de IA fundamentado no conteúdo da obra e um repositório vivo de conhecimento."],"challenge":["O projeto explora como manter a coerência de um universo literário ao permitir que leitores naveguem por personagens, documentos, mídia e interações mediadas por IA."],"solution":["A plataforma combina aplicação web, conteúdo narrativo, experiências com documentos e mídia, chatbot de IA fundamentado no conteúdo e um repositório vivo de conhecimento.","A orquestração multiagente combinando RAG e fine-tuning para agentes de IA específicos de personagens está atualmente em desenvolvimento."],"features":["Ambiente narrativo interativo","Chatbot de IA fundamentado no conteúdo da obra","Repositório vivo de conhecimento","Experiências com documentos e mídia","Pesquisa com agentes de IA específicos de personagens em desenvolvimento"],"role":["Desenvolvimento de produto e software envolvendo experiência narrativa, estrutura da aplicação, integração de IA e evolução da arquitetura do sistema de conhecimento."],"technologies":["Chatbot de IA","LLM","RAG","Repositório de Conhecimento","Sistemas Multiagente","Fine-Tuning","React","TypeScript","Aplicação Web"]}'::jsonb,
  technologies = array['AI Chatbot','LLM','RAG','Knowledge Repository','Multi-Agent Systems','Fine-Tuning','React','TypeScript','Web Application'],
